function extractUrls(text) {
  const seen = new Set();
  const result = [];
  const urlRegex = /^https?:\/\/[^\s]+/;

  for (const match of text.matchAll(urlRegex)) {
    const url = match[0];
    if (!seen.has(url)) {
      seen.add(url);
      result.push(url);
    }
  }

  return result;
}
