function isPalindrome(s) {
  const clean = s
    .split('')
    .filter(c => /[a-zA-Z0-9]/.test(c))
    .map(c => c.toLowerCase())
    .join('');

  const len = clean.length;
  for (let i = 0; i < Math.floor(len / 2); i++) {
    if (clean[i] !== clean[len - 1 - i]) {
      return false;
    }
  }
  return true;
}
