function romanToInt(s) {
  const map = {
    I: 1,
    V: 5,
    X: 10,
    L: 50,
    C: 100,
    D: 500,
    M: 1000
  };

  let total = 0;
  let i = 0;
  const len = s.length;

  while (i < len) {
    const current = map[s[i]];
    const next = i + 1 < len ? map[s[i + 1]] : 0;

    if (next > current) {
      total -= current;
    } else {
      total += current;
    }

    i++;
  }

  return total;
}
